ground_truth:
def classify_pigeon_sound(frequency, loudness, is_alarm):
    if frequency > 2000 and loudness > 50 and is_alarm:
        return 'alarm'
    elif frequency < 1500 and loudness < 30 and not is_alarm:
        return 'normal'
    else:
        return 'unknown'

